function bindSelector(){
 const root=document.getElementById(rootId); if(!root||root.dataset.jlBound)return;
 root.dataset.jlBound="1";
 const trigger=root.querySelector(".jl-language-trigger");
 const menu=root.querySelector(".jl-language-menu");
 const closeBtn=root.querySelector(".jl-language-close");
 const MOBILE_BP=768;
 let backdrop=document.querySelector(".jl-language-backdrop");
 if(!backdrop){backdrop=document.createElement("div");backdrop.className="jl-language-backdrop";document.body.appendChild(backdrop);}
 function layoutMenu(){
  const isMobile=window.innerWidth<=MOBILE_BP;
  const isOpen=root.classList.contains("is-open");
  if(!menu) return;
  if(isMobile){
   menu.style.display=isOpen?"block":"none";
   menu.style.pointerEvents=isOpen?"auto":"none";
   backdrop.classList.toggle("is-visible",isOpen);
   document.body.style.overflow=isOpen?"hidden":"";
  }else{
   menu.style.display="";menu.style.pointerEvents="";
   backdrop.classList.remove("is-visible");
   document.body.style.overflow="";
  }
 }
 const close=()=>{root.classList.remove("is-open");trigger?.setAttribute("aria-expanded","false");layoutMenu();};
 trigger?.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();const open=root.classList.toggle("is-open");trigger.setAttribute("aria-expanded",open?"true":"false");layoutMenu();});
 closeBtn?.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();close();});
 backdrop.addEventListener("click",close);
 root.querySelectorAll(".jl-language-menu button[data-lang]").forEach(btn=>btn.addEventListener("click",e=>{e.preventDefault();e.stopPropagation();close();applyLanguage(btn.dataset.lang);}));
